<script setup lang="ts">
import{onMounted,ref}from'vue';import{request}from'../api/request';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import{useAuthStore}from'../stores/auth'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),d=ref<any>(),submitting=ref(false)
async function load(){d.value=await request.get('/api/inspection/tasks/'+route.params.id)}
async function action(x:string){submitting.value=true;try{await request.post('/api/inspection/tasks/'+route.params.id+'/'+x);ElMessage.success('操作成功');load()}finally{submitting.value=false}}
async function save(i:any){submitting.value=true;try{await request.put('/api/inspection/tasks/'+route.params.id+'/items/'+i.id,{actualValue:i.actualValue,resultStatus:i.resultStatus,remark:i.remark});ElMessage.success('已保存')}finally{submitting.value=false}}
onMounted(load)
</script><template><section><h1>巡检任务详情</h1><el-card v-loading="!d"><el-descriptions v-if="d?.task" :column="2"><el-descriptions-item label="任务">{{d.task.taskCode}}</el-descriptions-item><el-descriptions-item label="状态">{{d.task.taskStatus}}</el-descriptions-item></el-descriptions><el-button v-if="auth.can('inspection:execute')" :loading="submitting" @click="action('start')">开始任务</el-button><el-button v-if="auth.can('inspection:execute')" :loading="submitting" @click="action('complete')">完成任务</el-button><el-table :data="d?.items"><el-table-column prop="itemName" label="检查项"/><el-table-column label="实际值"><template #default="x"><el-input-number v-if="x.row.itemType==='NUMBER'" v-model="x.row.actualValue"/><el-switch v-else-if="x.row.itemType==='BOOLEAN'" v-model="x.row.actualValue" active-value="true" inactive-value="false"/><el-input v-else v-model="x.row.actualValue"/></template></el-table-column><el-table-column label="结果"><template #default="x"><el-input v-model="x.row.resultStatus"/></template></el-table-column><el-table-column><template #default="x"><el-button @click="save(x.row)">保存</el-button></template></el-table-column></el-table><h3>关联异常</h3><el-button v-for="a in d?.abnormals" :key="a.id" link @click="router.push('/inspection/abnormals/'+a.id)">{{a.abnormalCode}}</el-button></el-card></section></template>
